Here is the commit message:
ASoC: codecs: rt1011: Use component to get the dapm context
 in spk_mode_put

The correct helper to use in rt1011_recv_spk_mode_put() to retrieve the
DAPM context is snd_soc_component_to_dapm(), from kcontrol we will
receive NULL pointer.

Closes: https://github.com/thesofproject/linux/issues/5691
Fixes: 5b35bb517f27 ("ASoC: codecs: rt1011: convert to snd_soc_dapm_xxx()")
Signed-off-by: Peter Ujfalusi <peter.ujfalusi@linux.intel.com>
Link: https://patch.msgid.link/20260310065350.18921-1-peter.ujfalusi@linux.intel.com
Signed-off-by: Mark Brown <broonie@kernel.org>

Here is the root cause:
The function `rt1011_recv_spk_mode_put` incorrectly used `snd_soc_dapm_kcontrol_to_dapm(kcontrol)` to retrieve the DAPM context, but the kcontrol is not associated with a DAPM widget in this context, resulting in a NULL pointer dereference. The correct approach is to obtain the DAPM context from the component via `snd_soc_component_to_dapm(component)`.

Here is the patch:

 static int rt1011_recv_spk_mode_put(struct snd_kcontrol *kcontrol,
 		struct snd_ctl_elem_value *ucontrol)
 {
 	struct snd_soc_component *component = snd_kcontrol_chip(kcontrol);
-	struct snd_soc_dapm_context *dapm = snd_soc_dapm_kcontrol_to_dapm(kcontrol);
+	struct snd_soc_dapm_context *dapm = snd_soc_component_to_dapm(component);
 	struct rt1011_priv *rt1011 =
 		snd_soc_component_get_drvdata(component);

 	if (ucontrol->value.integer.value[0] == rt1011->recv_spk_mode)
 		return 0;

 	if (snd_soc_dapm_get_bias_level(dapm) == SND_SOC_BIAS_OFF) {
 		rt1011->recv_spk_mode = ucontrol->value.integer.value[0];

 		if (rt1011->recv_spk_mode) {

 			/* 1: recevier mode on */
 			snd_soc_component_update_bits(component,
 				RT1011_CLASSD_INTERNAL_SET_3,
 				RT1011_REG_GAIN_CLASSD_RI_SPK_MASK,
 				RT1011_REG_GAIN_CLASSD_RI_410K);
 			snd_soc_component_update_bits(component,
 				RT1011_CLASSD_INTERNAL_SET_1,
 				RT1011_RECV_MODE_SPK_MASK,
 				RT1011_RECV_MODE);
 		} else {
 			/* 0: speaker mode on */
 			snd_soc_component_update_bits(component,
 				RT1011_CLASSD_INTERNAL_SET_3,
 				RT1011_REG_GAIN_CLASSD_RI_SPK_MASK,
 				RT1011_REG_GAIN_CLASSD_RI_72P5K);
 			snd_soc_component_update_bits(component,
 				RT1011_CLASSD_INTERNAL_SET_1,
 				RT1011_RECV_MODE_SPK_MASK,
 				RT1011_SPK_MODE);
 		}
 	}

 	return 0;
 }



